from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'dist'/'admin';D.mkdir(exist_ok=True)
(D/'index.html').write_text('''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nginx 可视化转发配置器 · AIONE1</title><link rel="stylesheet" href="../assets/apps.css"><script src="admin.js" defer></script></head><body><main class="app"><header><a href="../">AIONE1 / 姚毛毛</a><span class="hint">Nginx 可视化转发配置器</span></header><section id="login" class="login panel"><p class="hint">ADMINISTRATOR ACCESS</p><h1>管理员登录</h1><p class="lead">配置各工具的访问入口与后端转发。只有口令验证通过，才能读取与修改服务器配置。</p><form id="login-form"><label for="password">管理员口令</label><input id="password" type="password" autocomplete="current-password" required placeholder="输入管理员口令"><button class="primary" id="login-button">进入配置器 →</button></form><p class="status" id="login-status" role="status"></p><div class="notice" id="transport" hidden>当前为公网 HTTP，管理操作暂不开放。请启用 HTTPS，或通过 SSH 隧道访问本机地址：<pre style="white-space:pre-wrap">ssh -L 18081:127.0.0.1:80 root@8.133.244.26</pre>然后打开 http://127.0.0.1:18081/admin/ 。</div></section><section id="dashboard" hidden><div class="admin-summary"><div><p class="hint">NGINX / VISUAL ROUTING</p><h1>每个工具，各就其位。</h1></div><button id="logout">退出登录</button></div><p class="lead">静态页面由 Nginx 直接提供。需要服务端能力的工具可接入服务器本机后端端口，不为静态页面单独启动 Node。</p><div class="split"><section class="panel"><h2>工具路由 <small id="route-count"></small></h2><div id="routes"></div></section><section><div class="panel"><h2>配置预览</h2><p class="hint">点击「预览配置」生成待应用的配置；只有点击「校验并应用」才修改服务器。</p><pre class="code" id="nginx"></pre><div class="notice">转发前缀会被去掉，例如 /apps/avatar/api/health 转发到所设端口的 /api/health。后端应支持从子路径访问。后端端口只监听在本机，Nginx 负责对外入口。</div><div class="notice">数字人及其他未提供静态构建的项目可选宣传页或反向代理。选择代理前，请先安装对应后端并配置访问控制。</div></div></section></div><div class="actions"><button id="preview">预览配置</button><button id="apply" class="primary" disabled>校验并应用 Nginx</button><button id="export">下载配置</button><span id="save-status" class="status" role="status"></span></div></section></main></body></html>''',encoding='utf-8')
(D/'admin.js').write_text('''(()=>{const $=s=>document.querySelector(s);let csrf='',config=null,previewed='',lastText='';const modes=[['intro','宣传页'],['static','静态 dist'],['proxy','后端转发']];async function api(path,data){const res=await fetch('api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin'});const type=res.headers.get('content-type')||'';if(!type.includes('application/json'))throw Error('管理服务暂未接入，请检查 Nginx 与管理服务配置');const json=await res.json();if(!res.ok){if(res.status===401&&path!=='session'){csrf='';$('#dashboard').hidden=true;$('#login').hidden=false;}throw Error(json.error||'操作失败')}return json}function read(){return{routes:config.routes.map(r=>({id:r.id,name:r.name,mode:$('#mode-'+r.id).value,port:Number($('#port-'+r.id).value)}))}}function dirty(){previewed='';$('#apply').disabled=true;$('#save-status').textContent='修改后请先预览配置'}function render(){const root=$('#routes');root.replaceChildren();for(const row of config.routes){const box=document.createElement('div');box.className='route';const title=document.createElement('h3');title.textContent=row.name;const url=document.createElement('p');url.textContent='/apps/'+row.id+'/';const fields=document.createElement('div');fields.className='route-fields';const modeLabel=document.createElement('label');modeLabel.textContent='入口方式';const select=document.createElement('select');select.id='mode-'+row.id;for(const [v,label] of modes){if(v==='static'&&!['music','podcast','video','liubao'].includes(row.id))continue;const option=document.createElement('option');option.value=v;option.textContent=label;select.append(option)}select.value=row.mode;const portLabel=document.createElement('label');portLabel.textContent='本机后端端口';const port=document.createElement('input');port.id='port-'+row.id;port.type='number';port.min='1024';port.max='65535';port.value=row.port;port.disabled=row.mode!=='proxy';select.onchange=()=>{port.disabled=select.value!=='proxy';dirty()};port.oninput=dirty;modeLabel.append(select);portLabel.append(port);fields.append(modeLabel,portLabel);box.append(title,url,fields);root.append(box)}$('#route-count').textContent=' / '+config.routes.length}async function open(){const data=await api('config');config=data.config;lastText=data.nginx;$('#nginx').textContent=lastText;render();$('#login').hidden=true;$('#dashboard').hidden=false}$('#login-form').onsubmit=async e=>{e.preventDefault();$('#login-button').disabled=true;try{const data=await api('session',{password:$('#password').value});csrf=data.csrf;$('#password').value='';await open()}catch(e){$('#login-status').textContent=e.message}finally{$('#login-button').disabled=false}};$('#preview').onclick=async()=>{try{const data=read();const result=await api('preview',data);lastText=result.nginx;$('#nginx').textContent=lastText;previewed=JSON.stringify(data);$('#apply').disabled=false;$('#save-status').textContent='预览已生成；尚未改动服务器'}catch(e){$('#save-status').textContent=e.message}};$('#apply').onclick=async()=>{const data=read();if(JSON.stringify(data)!==previewed){dirty();return}$('#apply').disabled=true;$('#save-status').textContent='正在校验并应用…';try{const result=await api('apply',data);config=result.config;lastText=result.nginx;$('#nginx').textContent=lastText;$('#save-status').textContent=result.message;previewed=''}catch(e){$('#save-status').textContent=e.message}};$('#export').onclick=()=>{if(!lastText)return;const url=URL.createObjectURL(new Blob([lastText],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='aione1-routes.conf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#logout').onclick=async()=>{try{await api('logout',{});location.reload()}catch(e){$('#save-status').textContent=e.message}};api('session').then(async data=>{$('#transport').hidden=data.transportAllowed;$('#login-button').disabled=!data.transportAllowed;if(data.authenticated){csrf=data.csrf;await open()}}).catch(e=>$('#login-status').textContent=e.message)})();''',encoding='utf-8')
text=(D/'admin.js').read_text('utf-8').replace("['music','podcast','video','liubao']","['music','podcast','video','liubao','avatar']").replace("port.disabled=row.mode!=='proxy'","port.disabled=row.mode!=='proxy'&&row.id!=='avatar'").replace("port.disabled=select.value!=='proxy'","port.disabled=select.value!=='proxy'&&row.id!=='avatar'")
(D/'admin.js').write_text(text,encoding='utf-8')
